int l = 0, r = n - 1, lm = 0, rm = 0;
long long water = 0;
while (l < r) {
    if (a[l] <= a[r]) {
        lm = max(lm, a[l]);
        water += lm - a[l++];
    } else {
        rm = max(rm, a[r]);
        water += rm - a[r--];
    }
}

