int i = n - 2;
while (i >= 0 && a[i] >= a[i+1]) i--;     // find pivot
if (i >= 0) {
    int j = n - 1;
    while (a[j] <= a[i]) j--;             // successor
    swap(a[i], a[j]);
}
reverse(a.begin() + i + 1, a.end());       // last perm wraps to first
